using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpWebService.Tools;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo(
        [Description("The message to echo")] string message) =>
        $"Echo: {message}";

    [McpServerTool, Description("Returns the current server UTC time.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("O");
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpWebService.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpWebService",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns the current feature flag settings.")]
    public static string GetFeatureFlags()
    {
        var flags = new
        {
            EnableCaching = true,
            EnableMetrics = false,
            EnableDetailedErrors = false
        };

        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

